detaileddescription.para:
If SD0 and SD1 are not configured to the same direction (or only one is used) then the structure can be simplified as below: struct
{
#ifUSE_CHANNEL_0
uint8_tchannel0SampleWord[BYTES_PER_WORD];
#endif
#ifUSE_CHANNEL_1
uint8_tchannel1SampleWord[BYTES_PER_WORD];
#endif
//...
#ifUSE_CHANNEL_8
uint8_tchannel8SampleWord[BYTES_PER_WORD];
#endif
}sampleBufferFrames[FRAMES_PER_BUFFER];
